generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment 
       (SUM(xsd:decimal(?cashAmt)) AS ?totalCashFlow) 
       (SUM(xsd:decimal(?allocChange)) AS ?totalAllocationChange) 
       (SUM(?scenarioCnt) AS ?totalScenarioCount)
WHERE {
  {
    SELECT ?investorId ?segment (SUM(xsd:decimal(?amount)) AS ?cashAmt)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:segment ?segment ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId ?segment
  }
  {
    SELECT ?investorId ?segment (SUM(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?allocChange) (COUNT(?scenario) AS ?scenarioCnt)
    WHERE {
      ?inv a wm:Investor ;
           wm:investorId ?investorId ;
           wm:segment ?segment ;
           wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?newAllocationPct ;
          wm:currentAllocationPct ?currentAllocationPct ;
          wm:scenario ?scenario .
    }
    GROUP BY ?investorId ?segment
  }
}
GROUP BY ?segment

